// Ownership is decided from the event Google actually holds, never from text the
// model supplied. The old guard compared ref: inside a description the agent
// retyped, so passing your own booking's description with someone else's event
// id would have passed it.
//
// The booking is resolved here rather than trusted. Two live failures drove this:
// the model invented an event id in the shape of the recurring-instance ids it
// had just seen, and - given a notice saying it could search to recover an id -
// it searched, got the id, and then stopped, re-presenting the same summary
// instead of cancelling. So the title it showed the requester resolves the
// booking too, and no search is needed on the turn they approve.
// Model output occasionally carries invisible characters. On 2026-08-30 a
// variation selector (U+FE0F) glued to the end of an ISO timestamp made Room
// Availability answer BAD_WINDOW, and the model then presented a booking
// summary as though the room were free. Every string the model hands this
// workflow is scrubbed once, here, rather than at each place one is read.
// Tabs and newlines survive - a description is allowed to contain them.
const clean = s => String(s == null ? '' : s)
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200F\u2028\u2029\u202A-\u202E\u2060-\u2064\uFE00-\uFE0F\uFEFF]/g, '')
  .trim();
const REQ = (function (o) {
  const out = {};
  for (const k in o) out[k] = (typeof o[k] === 'string') ? clean(o[k]) : o[k];
  return out;
})($('When Executed by Another Workflow').first().json || {});
const raw = $input.first().json || {};
const me  = String(REQ.requester || '').trim();
const confirmed = REQ.confirmed === true || String(REQ.confirmed).toLowerCase() === 'true';
const wantedId = String(REQ.event_id || '').trim();
const wantedTitle = String(REQ.title || '').trim();
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
// Levenshtein distance, used only to recognise a title the model mistyped.
const dist = (a, b) => {
  if (a === b) return 0;
  if (!a.length || !b.length) return Math.max(a.length, b.length);
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
};
// Two bookings can share a title on one day, so a list of them has to carry the
// time or there is nothing to choose between.
const when = e => {
  const s = (e.start && e.start.dateTime) || '';
  if (!s) return '(all day)';
  const d = new Date(s);
  return '(' + d.toLocaleTimeString('en-US', { timeZone:'Asia/Manila', hour:'numeric', minute:'2-digit' }) + ')';
};

if (!confirmed) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_CONFIRMED',
    human:'Nothing was cancelled. Show the requester the booking you found, end that message with the line "Confirm to cancel. (yes/no)", and stop. Cancel it only after they reply yes.' } }];
}
if (!String(REQ.booking_date || '').trim()) {
  return [{ json: { verdict:'REJECTED', reason:'MISSING_DATE',
    human:'Nothing was cancelled - no booking date was given. Call Cancel Booking again with the date you showed the requester.' } }];
}
if (!wantedId && !wantedTitle) {
  return [{ json: { verdict:'REJECTED', reason:'MISSING_DETAILS',
    human:'Nothing was cancelled - no booking title or event id was given. Call Cancel Booking again with the title exactly as you showed it to the requester.' } }];
}

const items = Array.isArray(raw.items) ? raw.items.filter(e => e.status !== 'cancelled') : null;
if (!items) {
  return [{ json: { verdict:'REJECTED', reason:'LOOKUP_FAILED',
    human:'Nothing was cancelled - the calendar could not be read for that date. Tell the requester it did not go through and offer to try again.' } }];
}

// The id if it is real, otherwise the title. An invented id no longer dead-ends
// a cancellation that named the booking correctly.
let ev = wantedId ? items.find(e => String(e.id) === wantedId) : null;
let how = ev ? 'id' : '';
if (!ev && wantedTitle) {
  const want = norm(wantedTitle);
  let hits = items.filter(e => norm(e.summary) === want);
  if (!hits.length) hits = items.filter(e => norm(e.summary).includes(want) || want.includes(norm(e.summary)));
  // The model corrupts strings it is copying back. During QA on 2026-08-30 it
  // rendered "REASON1 / Bea Jose / TL" as "REazon1 / Bea Jose / TL", re-sent
  // that on the confirming turn, and the move failed as NOT_ON_CALENDAR. A near
  // match is taken only when one booking that day is strictly closest, and the
  // ownership check below still runs on whatever it resolves to - so this
  // loosens how a booking may be named, never who is allowed to touch it.
  if (!hits.length) {
    const tol = Math.max(1, Math.floor(want.length * 0.15));
    const near = items.map(e => ({ e, d: dist(norm(e.summary), want) }))
                      .filter(x => x.d <= tol).sort((a, b) => a.d - b.d);
    if (near.length === 1 || (near.length > 1 && near[0].d < near[1].d)) { ev = near[0].e; how = 'near'; }
    else if (near.length > 1) hits = near.map(x => x.e);
  }
  if (!ev && hits.length === 1) { ev = hits[0]; how = 'title'; }
  else if (hits.length > 1) {
    return [{ json: { verdict:'REJECTED', reason:'AMBIGUOUS_TITLE',
      human:'Nothing was cancelled - more than one booking on that date matches "' + wantedTitle + '":\n'
        + hits.map(e => '- ' + (e.summary || '(no title)') + ' ' + when(e)).join('\n')
        + '\nAsk the requester which one they mean, then call Cancel Booking again with that exact title.' } }];
  }
}
if (!ev) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_ON_CALENDAR',
    human: 'Nothing was cancelled - no booking on that date matches what you gave. These are the only bookings on '
      + 'that date:\n' + (items.map(e => '- ' + (e.summary || '(no title)') + ' ' + when(e)).join('\n') || '(none)')
      + '\nIf one of them is the booking, call Cancel Booking again with that title exactly. If none of them is, '
      + 'tell the requester it was not found and ask them to check the date.' } }];
}

const desc = String(ev.description || '');
const ref  = desc.match(/ref:\s*([A-Za-z0-9]+)/);
const by   = desc.match(/Booked by:\s*([^|]+)/);
const who  = by ? by[1].trim() : '';
const title = ev.summary || '(no title)';

if (!ref) {
  return [{ json: { verdict:'REJECTED', reason:'NO_REFERENCE', title,
    human:'BLOCKED - "' + title + '" carries no booker reference, so there is no way to tell whose it is. It has to be cancelled by hand.' } }];
}
if (ref[1] !== me) {
  return [{ json: { verdict:'REJECTED', reason:'NOT_YOURS', title,
    human:'BLOCKED - "' + title + '" was booked by ' + (who || 'someone else') + ', so it is not yours to cancel. Say exactly that to the requester and stop. Do not search again and do not show the booking again.' } }];
}
return [{ json: { verdict:'CLEAR', event_id: ev.id, title, matched_on: how,
  start: (ev.start && (ev.start.dateTime || ev.start.date)) || '' } }];

const c = $('Check Ownership').first().json;
return [{ json: { status:'CANCELLED', event_id: c.event_id, title: c.title,
  human:'Cancelled "' + c.title + '".' } }];

const v = $input.first().json || {};
return [{ json: { status:'REJECTED', reason: v.reason || 'FAILED',
  human: v.human || 'Nothing was cancelled and the reason is unclear. Tell the requester it did not go through.' } }];

